252	    @Override
253	    @Transactional
254	    public void saveOwner(Owner owner) throws DataAccessException {
255	        if (owner.isNew()) {
256	            LocalDate effectiveDate = owner.getRegistrationDate() != null
257	                ? owner.getRegistrationDate()
258	                : LocalDate.now();
259	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
260	            if (owner.getCustomerCode() == null) {
261	                owner.setCustomerCode(generateCustomerCode(owner));
262	            }
263	            if (owner.getNamesakeCount() == null) {
264	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
265	            }
266	        }
267	        ownerRepository.save(owner);
268	        decorateWithHouseholdMemberCount(owner);
269	    }
270	
271	    /**
272	     * Count the existing owners (before this create) that share the given first and last name,
273	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
274	     */
275	    private int countNamesakes(String firstName, String lastName) {
276	        if (firstName == null || lastName == null) {
277	            return 0;
278	        }
279	        return (int) ownerRepository.findAll().stream()
280	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
281	                && lastName.equalsIgnoreCase(owner.getLastName()))
282	            .count();
283	    }
284	
285	    /**
286	     * Build a customer code formatted {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
287	     * canonical region derived from the owner's postcode (falling back to the city-to-region
288	     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}) and {@code HASH8}
289	     * is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the owner's
290	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). There
291	     * is no sequence number: identity is fully determined by the region and the telephone/last
292	     * name hash.
293	     */
294	    private String generateCustomerCode(Owner owner) {
295	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
296	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
297	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
298	        return region + "-" + hash8(telephone + lastName);
299	    }
300	
301	    /**
302	     * The first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
303	     * of the UTF-8 bytes of {@code value}, used as the hash segment of the customer code.
304	     */
305	    private static String hash8(String value) {
306	        try {
307	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
308	            StringBuilder sb = new StringBuilder(8);
309	            for (int i = 0; i < 4; i++) {
310	                sb.append(String.format("%02X", digest[i]));
311	            }
312	            return sb.toString();
313	        } catch (NoSuchAlgorithmException ex) {
314	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
315	        }
316	    }
317	
318	    /**
319	     * Count the existing owners whose city matches the given city, compared case-insensitively,
320	     * used to derive the per-city sequence of the customer code.
321	     */
322	    private long countOwnersInCity(String city) {
323	        if (city == null) {
324	            return 0L;
325	        }
326	        return ownerRepository.findAll().stream()
