349	    /**
350	     * Count the owners whose registration date equals today's business day, used by the
351	     * daily create-limit and bulk-signup rules.
352	     */
353	    private long countRegisteredToday() {
354	        LocalDate businessDay = toBusinessDay(LocalDate.now());
355	        return ownerRepository.findAll().stream()
356	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
357	            .count();
358	    }
