360	    /**
361	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced
362	     * to the following Monday, while a weekday is returned unchanged. Applied to the effective
363	     * registration date (whether supplied or defaulted to the server date) so that the stored
364	     * {@code registrationDate}, every value derived from it (such as the membership number's year
365	     * segment) and the per-day create-limit all use the adjusted business day.
366	     */
367	    private static LocalDate toBusinessDay(LocalDate date) {
368	        DayOfWeek day = date.getDayOfWeek();
369	        if (day == DayOfWeek.SATURDAY) {
370	            return date.plusDays(2);
371	        }
372	        if (day == DayOfWeek.SUNDAY) {
373	            return date.plusDays(1);
374	        }
375	        return date;
376	    }
