388	    @Override
389	    @Transactional(readOnly = true)
390	    public String householdIdFor(String lastName, String address) throws DataAccessException {
391	        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
392	        try {
393	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
394	            StringBuilder sb = new StringBuilder(32);
395	            for (int i = 0; i < 8; i++) {
396	                sb.append(String.format("%02X", digest[i]));
397	            }
398	            return sb.toString();
399	        } catch (NoSuchAlgorithmException ex) {
400	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
401	        }
402	    }
403	
404	    /**
405	     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
406	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
407	     * spaced but equivalent values compare equal.
408	     */
409	    private static String normalizeHouseholdValue(String value) {
410	        if (value == null) {
411	            return "";
412	        }
413	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
414	    }
415	
416	    /**
417	     * Normalizes an address for household comparison by first applying the canonical address
418	     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
419	     * then the shared household-value normalization, so every address comparison uses the same
420	     * normalized form regardless of how the value was originally supplied.
421	     */
422	    private static String normalizeHouseholdAddress(String address) {
423	        return normalizeHouseholdValue(AddressNormalizer.normalize(address));
424	    }
425	
426	    /**
427	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
428	     * owners that share its {@code householdId}. Owners without a household id are left at a count
429	     * of zero.
430	     *
431	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
432	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
433	     */
434	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
435	        if (!owners.isEmpty()) {
436	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
437	                .filter(owner -> owner.getHouseholdId() != null)
438	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
439	            for (Owner owner : owners) {
440	                long size = owner.getHouseholdId() == null
441	                    ? 0L
442	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
443	                owner.setHouseholdMemberCount((int) size);
444	            }
445	        }
446	        return result;
447	    }
448	
449	    /**
450	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
451	     */
452	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
453	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
454	    }
